<script>
const STEPS = [
  ["connect",  "Connecting to the server"],
  ["discover", "Reading what it offers"],
  ["analyze",  "Checking for hidden instructions"],
  ["probe",    "Safely trying its tools"],
  ["report",   "Writing the verdict"],
];
const HUMAN = {
  tool_poisoning:        {label:"Hidden instructions in a tool", why:"A tool description contains orders aimed at your AI instead of describing what the tool does. Agents tend to follow text they read.", fragment:"hides instructions aimed at your AI"},
  prompt_injection:      {label:"Server instructions steer your AI", why:"The server's own instructions try to change how your AI behaves rather than explain the server.", fragment:"tries to steer your AI through its instructions"},
  response_injection:    {label:"Tool output tries to hijack your AI", why:"A tool returned text that gives your AI new orders. Output like this is how agents get tricked into leaking data.", fragment:"returns output that tries to hijack your AI"},
  secret_leak:           {label:"Leaked credentials", why:"A tool returned something shaped like a real key or token. Anything that reads it, including your AI's logs, now has it.", fragment:"leaks a credential"},
  excessive_permissions: {label:"Dangerous capability", why:"A tool can do far more than this server needs, such as running commands or deleting data, and it is not marked as such.", fragment:"exposes dangerous capabilities"},
  context_bloat:         {label:"Wastes your AI's context window", why:"Every request your AI makes carries this server's tool list. Big lists cost money and dilute attention on every turn.", fragment:"eats a large share of your AI's context"},
  data_exfiltration:     {label:"Tries to send your data elsewhere", why:"Something in this server pushes your data toward a third party.", fragment:"tries to send your data elsewhere"},
  schema_quality:        {label:"Sloppy input validation", why:"A tool accepts arbitrary input, so your AI cannot tell what is valid and the server cannot reject bad calls.", fragment:"accepts poorly validated input"},
  tool_shadowing:        {label:"Impersonates another tool", why:"A tool name mimics a well-known tool, which can trick your AI into calling the wrong one.", fragment:"impersonates another tool"},
  insecure_transport:    {label:"Unencrypted connection", why:"Tool calls and any token you supply travel in plain text.", fragment:"talks over an unencrypted connection"},
  connectivity:          {label:"Could not connect", why:"Airlock could not open an MCP session, so nothing could be checked.", fragment:"could not be reached"},
};
const RUG = {label:"Changed its tools after use", why:"The server showed one set of tool definitions before use and a different set after. This is how a trusted server turns malicious later.", fragment:"changed its tools after being used"};
const VERDICT = {A:"Looks safe to connect.", B:"Mostly fine. Read the notes below.", C:"Connect with caution.", D:"Do not connect.", F:"Do not connect."};
const WEIGHT = {critical:30, high:15, medium:7, low:2, info:0};

let targets = [], report = null, probeCalls = [], es = null;
const $ = s => document.querySelector(s);
const esc = s => String(s ?? "").replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const human = f => (/rug pull/i.test(f.title) ? RUG : (HUMAN[f.category] || {label:f.category, why:f.detail, fragment:"has issues"}));
const bucket = f => (f.severity === "critical" || f.severity === "high") ? "serious" : f.severity === "medium" ? "note" : "minor";

async function init() {
  targets = await (await fetch("/targets")).json();
  const order = ["fixture-evil", "fixture-clean", "deepwiki", "huggingface", "context7"];
  $("#chips").innerHTML = order.map(id => targets.find(t => t.id === id)).filter(Boolean)
    .map(t => `<button type="button" class="chip mr-2 mb-2" data-url="${esc(t.url)}" title="${esc(t.description)}">${esc(t.label.replace("Fixture: ", "").replace(" demo server", " demo"))}</button>`).join("");
  $("#chips").querySelectorAll("button").forEach(b => b.onclick = () => { $("#url-input").value = b.dataset.url; start(); });
  $("#token-toggle").onclick = () => { $("#token-input").classList.toggle("hidden"); $("#token-input").focus(); };
  $("#scan-form").onsubmit = e => { e.preventDefault(); start(); };
  loadRecent();
  route();
}

async function start() {
  const url = $("#url-input").value.trim();
  const err = $("#form-error"); err.classList.add("hidden");
  if (!/^https?:\/\//.test(url)) { err.textContent = "Enter a full URL starting with http:// or https://"; err.classList.remove("hidden"); return; }
  const preset = targets.find(t => t.url === url);
  const body = { url, label: preset ? preset.label : null };
  const tok = $("#token-input").value.trim(); if (tok) body.bearer_token = tok;
  $("#scan-btn").disabled = true; $("#scan-btn").textContent = "Starting…";
  try {
    const r = await fetch("/audits", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
    if (!r.ok) throw new Error((await r.json()).detail || r.statusText);
    location.hash = "#/scan/" + (await r.json()).audit_id;
  } catch (e) {
    err.textContent = "Could not start: " + e.message; err.classList.remove("hidden");
  } finally { $("#scan-btn").disabled = false; $("#scan-btn").textContent = "Scan server"; }
}

function watch(id) {
  if (es) es.close();
  report = { audit_id: id, url: "", target_label: "", phases: STEPS.map(([p]) => ({ phase: p, status: "pending", detail: "", seconds: null })), findings: [], inventory: null, grade: null };
  probeCalls = [];
  $("#scan").classList.remove("hidden"); $("#result").classList.add("hidden"); $("#result").innerHTML = "";
  renderScan();
  $("#scan").scrollIntoView({ behavior: "smooth", block: "start" });
  fetch(`/audits/${id}`).then(r => r.ok ? r.json() : null).then(r => { if (r && !report.grade) { report.url = r.url; report.target_label = r.target_label; renderScan(); } });
  es = new EventSource(`/audits/${id}/events`);
  es.addEventListener("phase", e => { const p = JSON.parse(e.data); Object.assign(report.phases.find(x => x.phase === p.phase), p); renderScan(); });
  es.addEventListener("probe_call", e => { probeCalls.push(JSON.parse(e.data)); renderScan(); });
  es.addEventListener("finding", e => { report.findings.push(JSON.parse(e.data)); });
  es.addEventListener("done", e => { report = JSON.parse(e.data); probeCalls = report.probe_calls; es.close(); renderScan(); renderResult(); loadRecent(); });
  es.addEventListener("error", e => { if (e.data) { $("#scan-status").textContent = "Error: " + JSON.parse(e.data).message; } });
}

function renderScan() {
  $("#scan-target").textContent = report.target_label || "Custom server";
  $("#scan-url").textContent = report.url || "";
  const running = report.phases.find(p => p.status === "running");
  $("#scan-status").innerHTML = report.grade ? `Done in ${report.phases.reduce((a, p) => a + (p.seconds || 0), 0).toFixed(1)}s`
    : running ? `<span class="inline-flex items-center gap-2"><span class="spin"></span>${esc(STEPS.find(s => s[0] === running.phase)[1])}…</span>` : "Starting…";
  $("#steps").innerHTML = STEPS.map(([key, label]) => {
    const p = report.phases.find(x => x.phase === key);
    const icon = p.status === "completed" ? `<span class="w-6 h-6 rounded-full bg-emerald-500 text-white grid place-items-center text-xs">✓</span>`
      : p.status === "running" ? `<span class="w-6 h-6 grid place-items-center"><span class="spin"></span></span>`
      : p.status === "failed" ? `<span class="w-6 h-6 rounded-full bg-red-500 text-white grid place-items-center text-xs">!</span>`
      : p.status === "skipped" ? `<span class="w-6 h-6 rounded-full bg-slate-200 text-slate-500 grid place-items-center text-xs">–</span>`
      : `<span class="w-6 h-6 rounded-full border-2 border-slate-200"></span>`;
    const calls = key === "probe" ? probeCalls.map(c => `<div class="mt-1.5 text-xs mono ${c.ok ? "text-slate-600" : "text-amber-700"}">${c.ok ? "✓" : "✕"} ${esc(c.tool)}(${esc(JSON.stringify(c.arguments).slice(0, 60))})${c.note ? ` <span class="font-sans">· ${esc(c.note)}</span>` : ""}</div>`).join("") : "";
    return `<li class="flex gap-3 items-start"><div class="mt-0.5">${icon}</div><div class="flex-1 min-w-0"><div class="flex justify-between gap-3"><span class="font-medium ${p.status === "pending" ? "text-slate-400" : ""}">${label}</span><span class="text-xs text-slate-400">${p.seconds != null && p.status !== "running" ? p.seconds + "s" : ""}</span></div>${p.detail ? `<div class="text-sm text-slate-500">${esc(p.detail)}</div>` : ""}${calls}</div></li>`;
  }).join("");
}

function verdictSentence(r) {
  if (!r.findings.length) return "We connected, read every tool, and tried the safe ones. Nothing suspicious turned up.";
  const ranked = [...r.findings].sort((a, b) => WEIGHT[b.severity] - WEIGHT[a.severity]);
  const frags = []; for (const f of ranked) { const fr = human(f).fragment; if (!frags.includes(fr)) frags.push(fr); if (frags.length === 2) break; }
  return "This server " + frags.join(" and ") + ".";
}

function renderResult() {
  const r = report, inv = r.inventory || {};
  const groups = { serious: [], note: [], minor: [] };
  for (const f of r.findings) groups[bucket(f)].push(f);
  const circ = 2 * Math.PI * 44, off = circ * (1 - (r.score || 0) / 100);
  const card = f => { const h = human(f); return `
    <div class="card p-5">
      <div class="flex flex-wrap items-center gap-2">
        <span class="sev-${bucket(f)} text-[11px] font-bold uppercase tracking-wide rounded-full px-2.5 py-1">${f.severity}</span>
        <span class="font-semibold">${esc(h.label)}</span>
        <span class="text-xs text-slate-400 mono ml-auto">${esc(f.location)}</span>
      </div>
      <p class="text-sm text-slate-700 mt-2">${esc(h.why)}</p>
      <p class="text-sm text-slate-500 mt-1">${esc(f.detail)}</p>
      ${f.recommendation ? `<p class="text-sm mt-2"><span class="font-medium text-slate-900">What to do:</span> ${esc(f.recommendation)}</p>` : ""}
      ${f.evidence ? `<details class="mt-3"><summary class="text-sm font-medium text-indigo-700">Show evidence</summary><pre class="mt-2 p-3 rounded-xl bg-slate-50 text-xs mono text-red-700 whitespace-pre-wrap">${esc(f.evidence)}</pre></details>` : ""}
    </div>`; };
  const group = (title, sub, list) => list.length ? `<div class="mt-8"><h3 class="font-bold text-lg">${title} <span class="text-slate-400 font-medium">${list.length}</span></h3><p class="text-sm text-slate-500">${sub}</p><div class="grid gap-3 mt-3">${list.map(card).join("")}</div></div>` : "";
  const tools = (inv.tools || []);
  $("#result").innerHTML = `
    <div class="card p-6 sm:p-8 g-${r.grade} max-w-3xl mx-auto">
      <div class="flex flex-col sm:flex-row gap-6 items-center">
        <div class="relative w-32 h-32 shrink-0">
          <svg viewBox="0 0 100 100" class="w-32 h-32 -rotate-90"><circle cx="50" cy="50" r="44" fill="none" stroke="#e2e8f0" stroke-width="8"/><circle class="ring" cx="50" cy="50" r="44" fill="none" stroke="var(--g)" stroke-width="8" stroke-linecap="round" stroke-dasharray="${circ}" stroke-dashoffset="${off}"/></svg>
          <div class="absolute inset-0 grid place-items-center"><div class="text-center"><div class="text-4xl font-extrabold" style="color:var(--g)">${r.grade}</div><div class="text-xs text-slate-500 -mt-1">${r.score}/100</div></div></div>
        </div>
        <div class="text-center sm:text-left">
          <div class="text-xs font-semibold tracking-widest text-slate-500 uppercase">Verdict</div>
          <div class="text-2xl sm:text-3xl font-extrabold tracking-tight mt-1" style="color:var(--g)">${VERDICT[r.grade]}</div>
          <p class="text-slate-700 mt-2">${esc(verdictSentence(r))}</p>
          <div class="text-sm text-slate-500 mt-2">${esc(r.target_label || "")} <span class="mono text-xs">${esc(r.url)}</span></div>
        </div>
      </div>
      <div class="grid grid-cols-3 gap-3 mt-6 text-center">
        <div class="rounded-xl bg-white/70 p-3"><div class="text-2xl font-extrabold text-red-600">${groups.serious.length}</div><div class="text-xs text-slate-500">serious problems</div></div>
        <div class="rounded-xl bg-white/70 p-3"><div class="text-2xl font-extrabold text-amber-600">${groups.note.length}</div><div class="text-xs text-slate-500">worth knowing</div></div>
        <div class="rounded-xl bg-white/70 p-3"><div class="text-2xl font-extrabold text-slate-800">${tools.length}</div><div class="text-xs text-slate-500">tools exposed · ${inv.total_tokens || 0} tokens</div></div>
      </div>
    </div>
    <div class="max-w-3xl mx-auto">
      ${group("Serious problems", "Reasons not to connect this server to an agent.", groups.serious)}
      ${group("Worth knowing", "Not dangerous on their own, but they cost you or hint at sloppiness.", groups.note)}
      ${group("Minor", "Housekeeping.", groups.minor)}
      <details class="card mt-10 overflow-hidden">
        <summary class="px-6 py-4 font-semibold flex items-center justify-between">Technical details <span class="text-slate-400 text-sm font-normal">tools, probe log, raw JSON</span></summary>
        <div class="px-6 pb-6 text-sm">
          <div class="grid sm:grid-cols-4 gap-3 mt-2">
            <div><div class="text-xs text-slate-500">Server</div><div class="font-medium">${esc(inv.server_name || "–")} ${esc(inv.server_version || "")}</div></div>
            <div><div class="text-xs text-slate-500">Transport</div><div class="font-medium">${esc(inv.transport || "–")} · ${inv.authenticated ? "bearer" : "no auth"}</div></div>
            <div><div class="text-xs text-slate-500">Protocol</div><div class="font-medium">${esc(inv.protocol_version || "–")}</div></div>
            <div><div class="text-xs text-slate-500">Model · tokens</div><div class="font-medium">${esc(r.model)} · ${(r.llm_usage || {}).prompt_tokens || 0}+${(r.llm_usage || {}).completion_tokens || 0}</div></div>
          </div>
          <h4 class="font-semibold mt-6 mb-2">Tools (${tools.length})</h4>
          <div class="overflow-x-auto"><table class="w-full text-xs"><thead class="text-left text-slate-500"><tr><th class="py-1 pr-3">Name</th><th class="pr-3">Tokens</th><th class="pr-3">Annotations</th><th>Description</th></tr></thead><tbody>
            ${tools.map(t => `<tr class="border-t align-top"><td class="py-1.5 pr-3 mono whitespace-nowrap">${esc(t.name)}</td><td class="pr-3">${t.tokens}</td><td class="pr-3 mono">${esc(JSON.stringify(t.annotations))}</td><td class="text-slate-600">${esc((t.description || "").slice(0, 200))}</td></tr>`).join("")}
          </tbody></table></div>
          <h4 class="font-semibold mt-6 mb-2">Probe log (${(r.probe_calls || []).length})</h4>
          ${(r.probe_calls || []).map(c => `<div class="border-t py-2"><div class="mono text-xs ${c.ok ? "" : "text-amber-700"}">${c.ok ? "✓" : "✕"} ${esc(c.tool)} ${esc(JSON.stringify(c.arguments))} <span class="text-slate-400">· ${c.response_tokens} tok · ${c.seconds}s</span></div>${c.note ? `<div class="text-xs text-slate-500">${esc(c.note)}</div>` : ""}${c.response_excerpt ? `<pre class="mt-1 text-xs mono text-slate-500 whitespace-pre-wrap">${esc(c.response_excerpt.slice(0, 300))}</pre>` : ""}</div>`).join("") || `<div class="text-slate-500">No tools were called.</div>`}
          <div class="flex flex-wrap gap-3 mt-6">
            <button id="dl" class="chip">Download JSON</button>
            <a class="chip" href="#/scan/${esc(r.audit_id)}">Permalink</a>
            <a class="chip" href="/audits/${esc(r.audit_id)}" target="_blank">Raw JSON</a>
          </div>
        </div>
      </details>
    </div>`;
  $("#result").classList.remove("hidden");
  $("#dl").onclick = () => { const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([JSON.stringify(r, null, 2)], { type: "application/json" })); a.download = `airlock-${r.audit_id}.json`; a.click(); };
}

async function loadRecent() {
  const rows = await (await fetch("/audits")).json();
  $("#recent").innerHTML = rows.slice(0, 6).map(x => `
    <a href="#/scan/${esc(x.audit_id)}" class="card p-5 g-${x.grade} hover:-translate-y-0.5 transition block">
      <div class="flex items-center gap-3"><span class="grade-badge w-11 h-11 rounded-xl grid place-items-center text-xl font-extrabold">${x.grade}</span>
        <div class="min-w-0"><div class="font-semibold truncate">${esc(x.target_label || x.server_name || "Custom server")}</div><div class="mono text-xs text-slate-500 truncate">${esc(x.url)}</div></div></div>
      <div class="text-xs text-slate-500 mt-3">Score ${x.score}/100 · ${esc((x.finished_at || "").replace("T", " ").slice(0, 16))}</div>
    </a>`).join("") || `<div class="text-slate-500 text-sm col-span-full text-center">No scans yet. Try one above.</div>`;
}

function route() {
  const m = (location.hash || "").match(/^#\/scan\/([a-z0-9]+)/);
  if (m) { if (!report || report.audit_id !== m[1]) watch(m[1]); }
  else { $("#scan").classList.add("hidden"); $("#result").classList.add("hidden"); if (es) es.close(); report = null; }
}
window.addEventListener("hashchange", route);
init();
</script>
</body>
</html>
