  const headers = { "content-type": "application/json" };
  if (settings.admin_required) {
    const tok = sessionStorage.getItem("airlock_admin") || prompt("Admin token to change analysis mode:");
    if (!tok) return;
    headers["X-Admin-Token"] = tok;
  }
  const r = await fetch("/settings", { method: "POST", headers, body: JSON.stringify({ llm_enabled: next }) });
