async function loadSettings() {
  try { settings = await (await fetch("/settings")).json(); } catch {}
  const on = settings.llm_enabled;
  $("#llm-label").textContent = on ? "Analysis: Deterministic + AI" : "Analysis: Deterministic only";
  $("#llm-dot").className = "w-2 h-2 rounded-full " + (on ? "bg-emerald-500" : "bg-slate-400");
}
async function toggleLlm() {
  const next = !settings.llm_enabled;
  const headers = { "content-type": "application/json" };
  if (settings.admin_required) {
    const tok = sessionStorage.getItem("airlock_admin") || prompt("Admin token to change analysis mode:");
    if (!tok) return;
    headers["X-Admin-Token"] = tok;
  }
  const r = await fetch("/settings", { method: "POST", headers, body: JSON.stringify({ llm_enabled: next }) });
  if (r.status === 401) { sessionStorage.removeItem("airlock_admin"); toast("Wrong admin token"); return; }
  if (settings.admin_required && r.ok) sessionStorage.setItem("airlock_admin", headers["X-Admin-Token"]);
  await loadSettings();
  toast(next ? "AI analysis on: judge + probing agent will run on new scans" : "AI analysis off: deterministic checks and probe only");
}

async function init() {
  if (new URLSearchParams(location.search).get("story") === "1") document.querySelector(".story").classList.remove("hidden");
  $("#llm-toggle").onclick = toggleLlm;
  loadSettings();

